function prepareAspectActions(context) {
  const keys = ['victory', 'obstacle', 'story', 'gratitude', 'joke', 'personalLife'];
  if (keys.some(key => typeof context?.aspects?.flags?.[key] !== 'boolean')) throw new Error('Aspectos inválidos para roteamento.');
  const active = keys.filter(key => context.aspects.flags[key]);
  return (active.length ? active : ['none']).map(aspect => ({ ...context, flags: context.aspects.flags, aspect }));
}
return prepareAspectActions($input.first().json).map(json=>({json}));

const context=$('Executar cada aspecto true').item.json;
const result=$input.first().json;
return [{json:{...context,...result,aspect:context.aspect,errors:{...context.errors,...result.errors}}}];

function combineFinalization(items) {
  if (!items.length || !items[0].aspects) throw new Error('Finalização sem resultados de aspectos.');
  const first = items[0];
  const errors = Object.assign({}, ...items.map(item => item.errors ?? {}));
  const victory = items.find(item => item.aspect === 'victory');
  return { ok: true, generatedContents:first.generatedContents??[], generatedContentErrors:first.generatedContentErrors??[], aspects: first.aspects, diary: first.diary ?? null,
    achievements: victory?.achievements ?? [], errors,
    activeRoutes: Object.keys(first.aspects.flags).filter(key => first.aspects.flags[key]),
    actionResults: items.filter(item => item.aspect !== 'none').map(item => ({ aspect: item.aspect, status: item.errors?.brag && item.aspect === 'victory' ? 'failed' : item.aspect === 'victory' ? 'completed' : 'no_behavior' })) };
}
return [{json:combineFinalization($input.all().map(item=>item.json))}];

const context=$input.first().json;
const text=context.text;
return [{json:{text,texto:text,referenceId:context.groupId,contentTitle:'Conteúdo do Diário',contentSourceIds:context.sourceIds,sourceWordCount:(text.match(/\S+/g)??[]).length}}];

function structureDiaryTweets(value, context) {
  const fail = message => ({ generatedContents: [], generatedContentErrors: [{ origin: 'diario',
    referenceId: context.referenceId, tweetIndex: context.tweetIndex ?? 1, message }] });
  if (value.error) return fail(String(value.error.message ?? value.error));
  let output = value.output;
  if (typeof output === 'string') {
    const trimmed = output.trim().replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i, '$1').trim();
    try { output = JSON.parse(trimmed); } catch { output = trimmed; }
  }
  const tweets = Array.isArray(output) ? output : Array.isArray(output?.tweets) ? output.tweets : [output];
  if (!tweets.length) return fail('O Agent não retornou tweets.');
  const generatedContents = [], generatedContentErrors = [], now = new Date().toISOString();
  for (const [index, tweet] of tweets.entries()) {
    const body = typeof tweet === 'string' ? tweet.trim() : typeof tweet?.text === 'string' ? tweet.text.trim()
      : typeof tweet?.body === 'string' ? tweet.body.trim() : '';
    if (!body) { generatedContentErrors.push(...fail(`Tweet ${index + 1} vazio ou inválido.`).generatedContentErrors); continue; }
    const tweetIndex = context.tweetIndex ?? index + 1;
    const contentKey = context.tweetIndex ? `tweet-${tweetIndex}${tweets.length > 1 ? `-${index + 1}` : ''}` : `tweet-${index + 1}`;
    const title = (typeof tweet?.title === 'string' && tweet.title.trim() ? tweet.title.trim()
      : context.angle ?? body.match(/^#{1,6}\s+(.+)$/m)?.[1] ?? body.split('\n').find(line => line.trim()) ?? 'Tweet').slice(0, 150);
    generatedContents.push({ schemaVersion: 1, origin: 'diario', referenceId: context.referenceId,
      sourceIds: context.contentSourceIds, contentKey, tweetIndex, angle: context.angle ?? null,
      createdAt: now, updatedAt: now, title, body, sourceWordCount: context.sourceWordCount,
      wordCount: (body.match(/\S+/g) ?? []).length });
  }
  return { generatedContents, generatedContentErrors };
}
const fallback=$('Contar palavras para conteúdo — Diário1').first().json;
return $input.all().flatMap((item,index)=>{
  let context=fallback;
  if ($('Edit Fields').isExecuted) context=$('Edit Fields').itemMatching(index).json;
  const result=structureDiaryTweets(item.json,context);
  return result.generatedContents.length
    ? result.generatedContents.map((content,contentIndex)=>({json:{generatedContents:[content],generatedContentErrors:contentIndex===0?result.generatedContentErrors:[]},pairedItem:{item:index}}))
    : [{json:result,pairedItem:{item:index}}];
});

function splitDiaryAngles(value, context) {
  const fail = message => [{ ...context, error: { message } }];
  if (value.error) return fail(String(value.error.message ?? value.error));
  let output = value.output;
  if (typeof output === 'string') {
    const trimmed = output.trim().replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i, '$1').trim();
    try { output = JSON.parse(trimmed); } catch { output = trimmed.split(/^\s*---+\s*$/m); }
  }
  const angles = Array.isArray(output) ? output : output?.angles ?? output?.angulos;
  if (!Array.isArray(angles) || !angles.length || angles.some(angle => typeof angle !== 'string' || !angle.trim())) {
    return fail('O Agent de ângulos não retornou uma lista válida de ângulos.');
  }
  return angles.map((angle, index) => ({ ...context, angle: angle.trim(), tweetIndex: index + 1,
    texto: `${context.text}\n\nÂngulo deste item: ${angle.trim()}`, error: null }));
}
const context=$('Contar palavras para conteúdo — Diário1').first().json;
return $input.all().flatMap((item,index)=>splitDiaryAngles(item.json,context).map(json=>({json,pairedItem:{item:index}})));
